  def('4-2-3-1', [s('m','M',['M'],39,57),s('mc','M/C',['M','C'],61,57)], [s('wt','W/T',['W','T'],18,32),s('t','T',['T'],50,31),s('wa','W/A',['W','A'],82,32),s('apc','A/Pc',['A','Pc'],50,12)], back4())
